_TOTAL_SEQ_LEN = None
_VISUAL_SEQ_LEN = None
_VISUAL_PER_SEQ_LEN = None

def get_seq_len(seq_type: str = None) -> int:
    if seq_type == "total":
        global _TOTAL_SEQ_LEN
        return _TOTAL_SEQ_LEN
    elif seq_type == "visual":
        global _VISUAL_SEQ_LEN
        return _VISUAL_SEQ_LEN
    elif seq_type == "per_visual":
        global _VISUAL_PER_SEQ_LEN
        return _VISUAL_PER_SEQ_LEN
    else:
        raise ValueError(
            f"Invalid sequence type: '{seq_type}'. Expected 'total' or 'visual'."
        )


def set_seq_len(seq_type: str = None, seq_len: Optional[Union[int, List[int]]] = None) -> None:
    if seq_type == "total":
        global _TOTAL_SEQ_LEN
        _TOTAL_SEQ_LEN = seq_len
    elif seq_type == "visual":
        global _VISUAL_SEQ_LEN
        _VISUAL_SEQ_LEN = seq_len
    elif seq_type == "per_visual":
        global _VISUAL_PER_SEQ_LEN
        _VISUAL_PER_SEQ_LEN = seq_len
    else:
        raise ValueError(
            f"Invalid sequence type: '{seq_type}'. Expected 'total' or 'visual'."
        )


def _validate_cp_topology(ps) -> None:
    """Reject CP layouts whose masks and recurrent states are not implemented."""
    if ps.is_ring_enable() or ps.is_kvallgather_enable():
        raise NotImplementedError(
            "Qwen4Exp Ulysses CP currently supports only ulysses_parallel_size > 1 "
            "with ring_attention_size=1 and kvallgather_parallel_size=1"
        )


def _ulysses_local_slice(x: torch.Tensor, ps, total_size: int, dim: int) -> torch.Tensor:
    """Select this rank's contiguous Ulysses shard from a full sequence tensor."""
    sizes = cal_split_sizes(total_size, ps.get_ulysses_group_size())
    rank = ps.get_ulysses_rank()
    offset = sum(sizes[:rank])
    return x.narrow(dim, offset, sizes[rank]).contiguous()


class Qwen4ExpTextRotaryEmbedding(nn.Module):
    def __init__(self, config: Qwen4ExpTextConfig, device=None):
        super().__init__()
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings

        self.config = config

        self.rope_type = self.config.rope_parameters["rope_type"]
        rope_init_fn: Callable = self.compute_default_rope_parameters
        if self.rope_type != "default":
            rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type]
        inv_freq, self.attention_scaling = rope_init_fn(self.config)

        self.inv_freq = nn.Buffer(inv_freq, persistent=False)
        self.original_inv_freq = nn.Buffer(inv_freq.clone(), persistent=False)
        self.mrope_section = config.rope_parameters.get("mrope_section", [11, 11, 10])

    @staticmethod
    def compute_default_rope_parameters(
        config: Qwen4ExpTextConfig, device=None, **kwargs
    ) -> tuple[torch.Tensor, float]:
        """
        Computes the inverse frequencies according to the original RoPE implementation
        Args:
            config ([`~transformers.PreTrainedConfig`]):
                The model configuration.
        Returns:
            Tuple of (`torch.Tensor`, `float`), containing the inverse frequencies for the RoPE embeddings and the
            post-processing scaling factor applied to the computed cos/sin (unused in this type of RoPE).
        """
        base = config.rope_parameters["rope_theta"]
        partial_rotary_factor = config.rope_parameters.get("partial_rotary_factor", 1.0)
        head_dim = getattr(config, "head_dim", None) or config.hidden_size // config.num_attention_heads
        dim = int(head_dim * partial_rotary_factor)

        attention_factor = 1.0  # Unused in this type of RoPE
        # Compute the inverse frequencies
        inv_freq = 1.0 / (base ** (torch.arange(0, dim, 2, dtype=torch.float) / dim))
        return inv_freq.to(device), attention_factor

    @torch.no_grad()
    @dynamic_rope_update
    def forward(self, x, position_ids):
        # In contrast to other models, Qwen4ExpText has different position ids for the grids
        # So position_ids is broadcast to (3, bs, positions) and freqs has shape (3, bs, positions, dim // 2)
        position_ids = position_ids.expand(3, -1, -1)
        freqs = position_ids[..., None].float() * self.inv_freq.to(device=x.device, dtype=torch.float)
        cos = freqs.cos() * self.attention_scaling
        sin = freqs.sin() * self.attention_scaling

        sin = self.recomposition_frequencies(sin)
        cos = self.recomposition_frequencies(cos)
        return cos.to(dtype=x.dtype), sin.to(dtype=x.dtype)

    def recomposition_frequencies(self, freq):
        """
        Recompose the frequencies into the final spatial layout used per each grid.
        """
        freqs_thw = freq[0]  # just overwrite the first dimension T
        for dim, offset in enumerate((1, 2), start=1):  # H, W
            length = self.mrope_section[dim] * 3
            idx = slice(offset, length, 3)
            freqs_thw[..., idx] = freq[dim, ..., idx]
        return torch.cat((freqs_thw, freqs_thw), dim=-1)


class Qwen4ExpTextRMSNorm(nn.Module):
    def __init__(self, dim: int, group_size: int | None = None, eps: float = 1e-6):
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.zeros(dim))
        self.group_size = group_size
        self._norm_ones = None
        if group_size is not None and dim % group_size != 0:
            raise ValueError(f"hidden_size ({dim}) must be divisible by group_size ({group_size}).")

    def _norm(self, x: torch.Tensor) -> torch.Tensor:
        if self.group_size is not None:
            x = x.reshape(*x.shape[:-1], -1, self.group_size)
        out = x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)
        return out.flatten(-2) if self.group_size is not None else out

    def forward(self, x):
        if not IS_NPU_AVAILABLE:
            output = self._norm(x.float())
            output = output * (1.0 + self.weight.float())
            return output.type_as(x)
        z = x.float()
        if self.group_size is not None:
            z = z.reshape(*z.shape[:-1], -1, self.group_size)
            if self._norm_ones is None or self._norm_ones.device != z.device:
                self._norm_ones = torch.ones(self.group_size, dtype=torch.float32, device=z.device)
            # A [H] gamma normalizes H only; [C,H] would reduce both axes.
            output = torch_npu.npu_rms_norm(z, self._norm_ones, self.eps)[0]
            output = output.flatten(-2) * (1.0 + self.weight.float())
        else:
            output = torch_npu.npu_rms_norm(z, 1.0 + self.weight.float(), self.eps)[0]
        return output.type_as(x)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.eps}"


# NOTE: the FLA package does not re-cast to `input_dtype` in its implementation, maybe we should do the same
@use_kernel_forward_from_hub("RMSNormGated")
class Qwen4ExpTextRMSNormGated(nn.Module):
    def __init__(self, hidden_size: int, eps: float = 1e-6, activation: str = "silu",
                 implementation: str = IMPL_EAGER) -> None:
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps
        self.activation = activation
        self.implementation = implementation

    def forward(self, hidden_states: torch.Tensor, gate: torch.Tensor) -> torch.Tensor:
        if self.implementation == IMPL_TRITON:
            from mindspeed_mm.fsdp.ops.rmsnorm_gated.rmsnorm_gated_triton import rmsnorm_gated

            return rmsnorm_gated(
                hidden_states, gate, self.weight, self.variance_epsilon, self.activation
            )
        input_dtype = hidden_states.dtype
        if IS_NPU_AVAILABLE:
            hidden_states = torch_npu.npu_rms_norm(hidden_states, self.weight, self.variance_epsilon)[0]
            hidden_states = hidden_states * ACT2FN[self.activation](gate)
        else:
            hidden_states = hidden_states.to(torch.float32)
            variance = hidden_states.pow(2).mean(-1, keepdim=True)
            # Norm before gate
            hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
            hidden_states = self.weight * hidden_states.to(input_dtype)
            hidden_states = hidden_states * ACT2FN[self.activation](gate.to(torch.float32)).to(input_dtype)
        return hidden_states


def apply_mask_to_padding_states(hidden_states, attention_mask):
    """
    Tunes out the hidden states for padding tokens, see https://github.com/state-spaces/mamba/issues/66
    """
    # NOTE: attention mask is a 2D boolean tensor
    if attention_mask is not None:
        dtype = hidden_states.dtype
        hidden_states = (hidden_states * attention_mask[:, :, None]).to(dtype)

    return hidden_states


@use_kernel_func_from_hub_with_fallback("causal_conv1d_update", "causal_conv1d")
def causal_conv1d_update(
    hidden_states: torch.Tensor,
    conv_state: torch.Tensor,
    weight: nn.Parameter,
    bias: nn.Parameter | None = None,
    activation: str | None = None,
):
    _, hidden_size, seq_len = hidden_states.shape
    state_len = conv_state.shape[-1]

    hidden_states_new = torch.cat([conv_state, hidden_states], dim=-1).to(weight.dtype)
    conv_state.copy_(hidden_states_new[:, :, -state_len:])
    out = F.conv1d(hidden_states_new, weight.unsqueeze(1), bias, padding=0, groups=hidden_size)
    out = out[:, :, -seq_len:]
    if activation is not None:
        out = ACT2FN[activation](out)
    return out.to(hidden_states.dtype)


@use_kernel_func_from_hub_with_fallback("causal_conv1d_fn", "causal_conv1d")
def causal_conv1d_fn(
    hidden_states: torch.Tensor,
    weight: nn.Parameter,
    bias: nn.Parameter | None = None,
    activation: str | None = None,
    **kwargs,
):
    _, hidden_size, seq_len = hidden_states.shape
    padding = weight.shape[-1] - 1

    out = F.conv1d(
        hidden_states.to(weight.dtype),
        weight=weight.unsqueeze(1),
        bias=bias,
        padding=padding,
        groups=hidden_size,
    )[:, :, :seq_len]
    if activation is not None:
        out = ACT2FN[activation](out)
    return out.to(hidden_states.dtype)


# NOTE: the FLA package computes `x / torch.sqrt((x * x).sum(dim=dim, keepdim=True) + eps)` instead, so if we align
# with the GatedRMSNorm, maybe we can make that change as well.
def l2norm(x: torch.FloatTensor, dim: int = -1, eps: float = 1e-6):
    """This function is intended to align with the l2norm implementation in the FLA library."""
    inv_norm = torch.rsqrt((x * x).sum(dim=dim, keepdim=True) + eps)
    return x * inv_norm


@use_kernel_func_from_hub_with_fallback("chunk_gated_delta_rule", "fla")
def torch_chunk_gated_delta_rule(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    chunk_size: int = 64,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = False,
    use_qk_l2norm_in_kernel: bool = False,
    **kwargs,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Computes the gated delta rule, by chunking along the sequence dimension.
    Args:
        query: Query tensor of shape [batch_size, sequence_length, num_k_heads, k_head_dim]
        key: Key tensor of shape [batch_size, sequence_length, num_k_heads, k_head_dim]
        value: Value tensor of shape [batch_size, sequence_length, num_v_heads, v_head_dim]. num_v_heads can be equal
            to num_k_heads, same for v_head_dim and k_head_dim.
        g: Decay (in log space) tensor of shape [batch_size, sequence_length, num_v_heads]: the recurrent state is
            multiplied by exp(g) at each step, so entries must be <= 0.
        beta: Beta tensor of shape [batch_size, sequence_length, num_v_heads]
        chunk_size: Size of the chunks along the sequence dimension.
        initial_state: The recurrent state, an optional tensor of shape [batch_size, num_v_heads, k_head_dim, v_head_dim]
        output_final_state: Whether to output the new recurrent state along with the output.
        use_qk_l2norm_in_kernel: If this flag is set to True, query and key vectors are L2-normalized.
    Returns:
        - The output tensor of shape [batch_size, sequence_length, num_v_heads, v_head_dim]
        - Either None or the new recurrent state tensor of shape [batch_size, num_v_heads, k_head_dim, v_head_dim]
    """
    initial_dtype = query.dtype
    batch_size, sequence_length, _, k_head_dim = key.shape
    num_v_heads, v_head_dim = value.shape[-2:]
    recurrent_state_shape = (batch_size, num_v_heads, k_head_dim, v_head_dim)
    padded_output_shape = (batch_size, num_v_heads, -1, v_head_dim)  # -1 is the padded sequence length
    decay = g  # rename for clarity: argument name must stay "g" to match flash_linear_attention's API

    # Make sure all tensors are fp32 and reshape them to [batch_size, num_*_heads, seqlen, ...]
    query, key, value, beta, decay = [
        x.transpose(1, 2).to(torch.float32, memory_format=torch.contiguous_format)
        for x in (query, key, value, beta, decay)
    ]
    # If enabled, normalize query and key vectors (in fp32 to match the FLA library)
    if use_qk_l2norm_in_kernel:
        query = l2norm(query, dim=-1, eps=1e-6)
        key = l2norm(key, dim=-1, eps=1e-6)
    # And always normalize queries by the head dimension
    scaling = query.shape[-1] ** -0.5
    query = query * scaling

    # Pad sequence length to be a multiple of chunk_size. Padding is described as (left_pad, right_pad) for each dim.
    pad_size = (chunk_size - sequence_length % chunk_size) % chunk_size
    query, key, value = (F.pad(x, (0, 0, 0, pad_size)) for x in (query, key, value))
    beta, decay = (F.pad(x, (0, pad_size)) for x in (beta, decay))

    total_sequence_length = sequence_length + pad_size
    num_chunks = total_sequence_length // chunk_size

    # Apply beta to K and V, which is the "learning rate" of the recurrent state for a given token, ie. how much the new
    # state influence the old state. Beta is often normalized to (0, 1) where 0 = no update; 1 = overwrite old state.
    v_beta = value * beta.unsqueeze(-1)
    k_beta = key * beta.unsqueeze(-1)

    # Reshape all tensors to chunk the sequence dimension (adds a new dimension of size chunk_size)
    query, key, k_beta, v_beta = [
        x.reshape(x.shape[0], x.shape[1], -1, chunk_size, x.shape[-1]) for x in (query, key, k_beta, v_beta)
    ]
    decay = decay.reshape(decay.shape[0], decay.shape[1], -1, chunk_size)

    # Create a chunk-sized strictly upper triangular mask, ie. the mask of what a causal chunk may not attend to
    strictly_upper_mask = torch.ones(chunk_size, chunk_size, dtype=torch.bool, device=query.device).triu(1)

    # Cumulative decay within each chunk (dim 3 is the position inside the chunk). Since decay is in log space,
    # cum_decay[..., t] is the log of a product of decays between the start of the chunk and position t
    cum_decay = decay.cumsum(dim=3)

    # First phase: compute intra-chunk quantities.
    # The pairwise decays: pairwise_decay[..., i, j] = exp(cum_decay_i - cum_decay_j) is the decay accumulated between
    # positions j and i of a chunk. Positive values are masked to -inf before exp to avoid overflow
    pairwise_decay = cum_decay.unsqueeze(4) - cum_decay.unsqueeze(3)
    pairwise_decay = pairwise_decay.masked_fill(strictly_upper_mask, float("-inf"))
    pairwise_decay = pairwise_decay.exp()  # with the exp, we exit log space, so we can apply this decay to the states

    # Compute auxiliary tensors: the Upper Triangular (ut) transform system and the intra-chunk attn (QK dot product)
    ut_system = (k_beta @ key.transpose(-1, -2)) * pairwise_decay
    intra_chunk_attn = (query @ key.transpose(-1, -2)) * pairwise_decay
    decayed_k_beta = k_beta * cum_decay.exp().unsqueeze(-1)

    # Gated delta attention uses a UT transform to condense several delta rule updates into a few matmuls. After the UT
    # system is solved, we can then compute the new_values (called "u" in the DeltaNet paper) and the decayed keys
    # reading the old state (k_cumdecay). In the update, the part of new_values that the old state already predicts is
    # subtracted out, so that only the correction is written to the recurrent state: this is the delta rule.

    # Not all export targets support the fast triangular solver, so we build the inverse by forward substitution then
    if not is_torchdynamo_exporting():
        new_values = torch.linalg.solve_triangular(ut_system, v_beta, upper=False, unitriangular=True)
        k_cumdecay = torch.linalg.solve_triangular(ut_system, decayed_k_beta, upper=False, unitriangular=True)
    else:
        ut_system = -ut_system.tril(-1)  # ut_system is masked to only keep the strictly lower triangle
        for i in range(1, chunk_size):
            row = ut_system[..., i, :i].clone()
            sub = ut_system[..., :i, :i].clone()
            ut_system[..., i, :i] = row + (row.unsqueeze(-1) * sub).sum(-2)
        ut_system = ut_system + torch.eye(chunk_size, dtype=ut_system.dtype, device=ut_system.device)
        new_values, k_cumdecay = ut_system @ v_beta, ut_system @ decayed_k_beta

    if initial_state is None:
        last_recurrent_state = torch.zeros(recurrent_state_shape, dtype=new_values.dtype, device=new_values.device)
    else:
        last_recurrent_state = initial_state.to(new_values)
    core_attn_out = torch.zeros_like(new_values)

    # Apply decay once rather than in each chunk
    query = query * cum_decay.exp().unsqueeze(-1)
    key = key * (cum_decay[..., -1:] - cum_decay).exp().unsqueeze(-1)
    chunk_decay = cum_decay[..., -1].exp()[..., None, None]

    # Second phase: the sequential scan over chunks
    for i in range(num_chunks):
        # Compute attention output for the current chunk: add the read of the previous recurrent state
        # (inter_chunk_attn) with the within-chunk attention (intra_chunk_attn)
        v_new = new_values[:, :, i] - k_cumdecay[:, :, i] @ last_recurrent_state
        inter_chunk_attn = query[:, :, i] @ last_recurrent_state
        core_attn_out[:, :, i] = inter_chunk_attn + intra_chunk_attn[:, :, i] @ v_new
        # Update the recurrent state: new recurrent state (S_t+1) = decayed old state (S_t * (I-βkk^T)) + update (βvk^T)
        last_recurrent_state = last_recurrent_state * chunk_decay[:, :, i] + key[:, :, i].transpose(-1, -2) @ v_new

    # Discard the final state if not requested
    last_recurrent_state = None if not output_final_state else last_recurrent_state
    # Reshape the output to the orignal shape: flatten the chunk dimension, then drop padding
    core_attn_out = core_attn_out.reshape(padded_output_shape)
    core_attn_out = core_attn_out[:, :, :sequence_length]
    # Convert back to the original shape [batch_size, sequence_length, num_v_heads, v_head_dim] and dtype
    core_attn_out = core_attn_out.transpose(1, 2).to(initial_dtype, memory_format=torch.contiguous_format)
    return core_attn_out, last_recurrent_state


@use_kernel_func_from_hub_with_fallback("fused_recurrent_gated_delta_rule", "fla")
def torch_recurrent_gated_delta_rule(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = False,
    use_qk_l2norm_in_kernel: bool = False,
    **kwargs,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Computes linear attention using the gated delta rule, by iterating over each token in the sequence dimension.
    Same args and return value as torch_chunk_gated_delta_rule, except for `chunk_size` because the sequence dim is not
    chunked."""
    initial_dtype = query.dtype
    batch_size, sequence_length, _, k_head_dim = key.shape
    num_v_heads, v_head_dim = value.shape[-2:]
    decay = g  # rename for clarity: argument name must stay "g" to match flash_linear_attention's API

    # Make sure all tensors are fp32 and reshape them to [batch_size, num_*_heads, seqlen, ...]
    query, key, value, beta, decay = [
        x.transpose(1, 2).to(torch.float32, memory_format=torch.contiguous_format)
        for x in (query, key, value, beta, decay)
    ]
    # If enabled, normalize query and key vectors (done once in fp32 for better accuracy)
    if use_qk_l2norm_in_kernel:
        query = l2norm(query, dim=-1, eps=1e-6)
        key = l2norm(key, dim=-1, eps=1e-6)

    # And always normalize queries by the head dimension
    query = query / (query.shape[-1] ** 0.5)

    # Create the storage for the last recurrent state, which will be updated in place. If a previous state is provided,
    # it is the starting point, otherwise start with a zeroed buffer.
    if initial_state is None:
        recurrent_state_shape = (batch_size, num_v_heads, k_head_dim, v_head_dim)
        last_recurrent_state = torch.zeros(recurrent_state_shape, dtype=value.dtype, device=value.device)
    else:
        last_recurrent_state = initial_state.to(value)
    core_attn_out = torch.zeros_like(value)

    # Loop over each token and update the recurrent state
    for i in range(sequence_length):
        q_t, k_t, v_t = query[:, :, i], key[:, :, i], value[:, :, i]
        # Decay the recurrent state
        decay_t = decay[:, :, i].exp()[..., None, None]
        last_recurrent_state = last_recurrent_state * decay_t
        # Update the recurrent state with the current token
        beta_t = beta[:, :, i].unsqueeze(-1)
        kv_mem = (last_recurrent_state * k_t.unsqueeze(-1)).sum(dim=-2)
        delta = (v_t - kv_mem) * beta_t
        last_recurrent_state = last_recurrent_state + k_t.unsqueeze(-1) * delta.unsqueeze(-2)
        # And use it to compute the attention output for the current token
        core_attn_out[:, :, i] = (last_recurrent_state * q_t.unsqueeze(-1)).sum(dim=-2)

    # Discard the final state if not requested
    last_recurrent_state = None if not output_final_state else last_recurrent_state
    # Convert back to the original shape [batch_size, sequence_length, num_v_heads, v_head_dim] and dtype
    core_attn_out = core_attn_out.transpose(1, 2).contiguous().to(initial_dtype)
    return core_attn_out, last_recurrent_state


@use_kernelized_func(
    [torch_recurrent_gated_delta_rule, torch_chunk_gated_delta_rule, causal_conv1d_fn, causal_conv1d_update]
)
class Qwen4ExpTextGatedDeltaNet(nn.Module):
    def __init__(self, config: Qwen4ExpTextConfig, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.num_v_heads = config.linear_num_value_heads
        self.num_k_heads = config.linear_num_key_heads
        self.head_k_dim = config.linear_key_head_dim
        self.head_v_dim = config.linear_value_head_dim
        self.key_dim = self.head_k_dim * self.num_k_heads
        self.value_dim = self.head_v_dim * self.num_v_heads

        self.conv_kernel_size = config.linear_conv_kernel_dim
        self.layer_idx = layer_idx
        self.activation = config.hidden_act
        self.layer_norm_epsilon = config.rms_norm_eps

        # QKV
        self.conv_dim = self.key_dim * 2 + self.value_dim
        self.conv1d = nn.Conv1d(
            in_channels=self.conv_dim,
            out_channels=self.conv_dim,
            bias=False,
            kernel_size=self.conv_kernel_size,
            groups=self.conv_dim,
            padding=self.conv_kernel_size - 1,
        )

        # time step projection (discretization)
        # instantiate once and copy inv_dt in init_weights of PretrainedModel
        self.dt_bias = nn.Parameter(torch.ones(self.num_v_heads))

        # Lower bound kept away from 0 so log(A) never becomes -inf
        A = torch.empty(self.num_v_heads).uniform_(0.01, 16)
        self.A_log = nn.Parameter(torch.log(A))
        self.norm = Qwen4ExpTextRMSNormGated(
            self.head_v_dim, eps=self.layer_norm_epsilon,
            activation=config.output_gate_type or config.hidden_act,
            implementation=config.rmsnormgated_implementation,
        )
        self.out_proj = nn.Linear(self.value_dim, self.hidden_size, bias=False)

        self.layer_type = config.layer_types[layer_idx]

        self.in_proj_qkv = nn.Linear(self.hidden_size, self.key_dim * 2 + self.value_dim, bias=False)
        self.in_proj_z = nn.Linear(self.hidden_size, self.value_dim, bias=False)
        self.in_proj_b = nn.Linear(self.hidden_size, self.num_v_heads, bias=False)
        self.in_proj_a = nn.Linear(self.hidden_size, self.num_v_heads, bias=False)

        self.causal_conv1d_implementation = config.causal_conv1d_implementation
        self.gdn_implementation = config.gdn_implementation
        self.skip_gdn_recompute = config.skip_gdn_recompute

        if self.gdn_implementation == IMPL_ASCENDC and self.causal_conv1d_implementation == IMPL_TRITON and IS_NPU_AVAILABLE:
            self.causal_conv1d_implementation = IMPL_TRITON_WITH_TRANSPOSE

        if self.causal_conv1d_implementation == IMPL_TRITON_WITH_TRANSPOSE and IS_NPU_AVAILABLE:
            from mindspeed_mm.fsdp.ops.gdn.triton_core.causal_conv1d import causal_conv1d_triton
            print_rank(logger.info, "Qwen4Exp causal_conv1d (with transpose) use NPU triton ops")
            self.causal_conv1d_fn = causal_conv1d_triton
        elif self.causal_conv1d_implementation == IMPL_TRITON and IS_NPU_AVAILABLE:
            from mindspeed_mm.fsdp.models.qwen3_5.causal_conv1d import causal_conv1d
            print_rank(logger.info, "Qwen4Exp causal_conv1d use NPU triton ops")
            self.causal_conv1d_fn = causal_conv1d
        elif self.causal_conv1d_implementation == IMPL_ASCENDC and IS_NPU_AVAILABLE:
            from mindspeed_mm.fsdp.ops.gdn.causal_conv1d_ascendc import causal_conv1d_ascendc
            print_rank(logger.info, "Qwen4Exp causal_conv1d use NPU AscendC ops")
            self.causal_conv1d_fn = causal_conv1d_ascendc
        else:
            self.causal_conv1d_implementation = IMPL_EAGER
            self.causal_conv1d_fn = causal_conv1d_fn

        if self.gdn_implementation == IMPL_TRITON:
            if IS_NPU_AVAILABLE:
                from mindspeed_mm.fsdp.ops.gdn.chunk_gated_delta_rule import chunk_gated_delta_rule
                print_rank(logger.info, "Qwen4ExpTextGatedDeltaNet use NPU triton fused ops")
                self.chunk_gated_delta_rule = chunk_gated_delta_rule
            else:
                raise ValueError(
                    "gdn_implementation='triton' requires NPU, but NPU is not available. "
                    "Please use gdn_implementation='eager'."
                )
        elif self.gdn_implementation == IMPL_ASCENDC:
            if IS_NPU_AVAILABLE:
                from mindspeed_mm.fsdp.ops.gdn.flash_gated_delta_rule import flash_gated_delta_rule
                print_rank(logger.info, "Qwen4ExpTextGatedDeltaNet (without transpose) use NPU AscendC fused ops")
                self.chunk_gated_delta_rule = partial(
                    flash_gated_delta_rule, using_l2norm_in_gdn=config.using_l2norm_in_gdn
                )
            else:
                raise ValueError(
                    "gdn_implementation='ascendc' requires NPU, but NPU is not available. "
                    "Please use gdn_implementation='eager'."
                )
        elif self.gdn_implementation == IMPL_ASCENDC_LEGACY:
            if IS_NPU_AVAILABLE:
                from mindspeed_mm.fsdp.ops.gdn.flash_chunk_gated_delta_rule import chunk_gated_delta_rule
                print_rank(logger.info, "Qwen4ExpTextGatedDeltaNet (with transpose) use NPU AscendC fused ops")
                self.chunk_gated_delta_rule = chunk_gated_delta_rule
            else:
                raise ValueError(
                    "gdn_implementation='ascendc_legacy' requires NPU, but NPU is not available. "
                    "Please use gdn_implementation='eager'."
                )
        elif self.gdn_implementation == IMPL_EAGER:
            self.chunk_gated_delta_rule = torch_chunk_gated_delta_rule
        self.recurrent_gated_delta_rule = torch_recurrent_gated_delta_rule

    def _get_local_conv1d_weight(self, ulysses_rank: int, local_key_dim: int, local_value_dim: int) -> torch.Tensor:
        """Select depthwise convolution channels after the Ulysses head exchange."""
        full = self.conv1d.weight
        if full.shape[0] != self.conv_dim:
            raise ValueError(
                f"conv1d weight dim ({full.shape[0]}) must match conv_dim ({self.conv_dim})"
            )
        key_offset = ulysses_rank * local_key_dim
        value_offset = ulysses_rank * local_value_dim
        q_weight = full[key_offset:key_offset + local_key_dim]
        k_weight = full[self.key_dim + key_offset:self.key_dim + key_offset + local_key_dim]
        v_weight = full[2 * self.key_dim + value_offset:2 * self.key_dim + value_offset + local_value_dim]
        return torch.cat((q_weight, k_weight, v_weight), dim=0)

    def _get_local_conv1d_bias(self, ulysses_rank: int, local_key_dim: int, local_value_dim: int):
        if self.conv1d.bias is None:
            return None
        full = self.conv1d.bias
        key_offset = ulysses_rank * local_key_dim
        value_offset = ulysses_rank * local_value_dim
        return torch.cat(
            (
                full[key_offset:key_offset + local_key_dim],
                full[self.key_dim + key_offset:self.key_dim + key_offset + local_key_dim],
                full[2 * self.key_dim + value_offset:2 * self.key_dim + value_offset + local_value_dim],
            ),
            dim=0,
        )

    def forward(
        self,
        hidden_states: torch.Tensor,
        cache_params: Cache | None = None,
        attention_mask: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ):
        hidden_states = apply_mask_to_padding_states(hidden_states, attention_mask)

        # Set up dimensions for reshapes later
        batch_size, seq_len, _ = hidden_states.shape
        ps = get_parallel_state()
        _validate_cp_topology(ps)
        if ps.is_ulysses_enable() and cache_params is not None:
            raise NotImplementedError("Qwen4Exp GDN Ulysses CP currently supports training prefill only")
        use_precomputed_states = cache_params is not None and cache_params.has_previous_state(
            self.layer_idx, state_idx=0
        )

        mixed_qkv = self.in_proj_qkv(hidden_states)  # b s (k+k+v)d

        z = self.in_proj_z(hidden_states)
        z = z.reshape(batch_size, seq_len, -1, self.head_v_dim)

        b = self.in_proj_b(hidden_states)
        a = self.in_proj_a(hidden_states)

        if ps.is_ulysses_enable():
            ulysses_group = ps.get_ulysses_group()
            ulysses_size = ps.get_ulysses_group_size()
            ulysses_rank = ps.get_ulysses_rank()
            if self.num_k_heads % ulysses_size != 0 or self.num_v_heads % ulysses_size != 0:
                raise ValueError(
                    f"Ulysses size ({ulysses_size}) must divide GDN key heads ({self.num_k_heads}) "
                    f"and value heads ({self.num_v_heads})"
                )
            total_seq_len = get_seq_len("total")
            if total_seq_len is None:
                raise RuntimeError("set_seq_len('total', ...) must run before Qwen4Exp GDN")
            local_num_k_heads = self.num_k_heads // ulysses_size
            local_num_v_heads = self.num_v_heads // ulysses_size
            local_key_dim = self.head_k_dim * local_num_k_heads
            local_value_dim = self.head_v_dim * local_num_v_heads
            conv_weight = self._get_local_conv1d_weight(ulysses_rank, local_key_dim, local_value_dim)
            conv_bias = self._get_local_conv1d_bias(ulysses_rank, local_key_dim, local_value_dim)
            q_proj, k_proj, v_proj = torch.split(
                mixed_qkv, [self.key_dim, self.key_dim, self.value_dim], dim=-1
            )
            q_proj = all_to_all(q_proj, ulysses_group, scatter_dim=2, gather_dim=1, gather_size=total_seq_len)
            k_proj = all_to_all(k_proj, ulysses_group, scatter_dim=2, gather_dim=1, gather_size=total_seq_len)
            v_proj = all_to_all(v_proj, ulysses_group, scatter_dim=2, gather_dim=1, gather_size=total_seq_len)
            b = all_to_all(b, ulysses_group, scatter_dim=2, gather_dim=1, gather_size=total_seq_len)
            a = all_to_all(a, ulysses_group, scatter_dim=2, gather_dim=1, gather_size=total_seq_len)
            mixed_qkv = torch.cat((q_proj, k_proj, v_proj), dim=-1)
        else:
            local_num_k_heads = self.num_k_heads
            local_num_v_heads = self.num_v_heads
            local_key_dim = self.key_dim
            local_value_dim = self.value_dim
            conv_weight = self.conv1d.weight
            conv_bias = self.conv1d.bias

        cu_seqlens = None
        if kwargs.get("cu_seq_lens_q") is not None:
            cu_seqlens = kwargs.get("cu_seq_lens_q").to(torch.int64)

        if use_precomputed_states and seq_len == 1 and not cache_params.layers[self.layer_idx].record_past:
            conv_state = cache_params.layers[self.layer_idx].conv_states[0]
            # Single-token cached decode: the fused per-step kernel updates the conv state in-place.
            mixed_qkv = causal_conv1d_update(
                mixed_qkv.transpose(1, 2),
                conv_state,
                self.conv1d.weight.squeeze(1),
                self.conv1d.bias,
                self.activation,
            ).transpose(1, 2)
        else:
            if cache_params is not None:
                mixed_qkv_t = mixed_qkv.transpose(1, 2)
                mixed_qkv_t = cache_params.update_conv_state(
                    mixed_qkv_t, self.layer_idx, conv_kernel_size=self.conv_kernel_size
                )
                mixed_qkv = mixed_qkv_t.transpose(1, 2)

            # Modification: NPU causal_conv1d implementations (ported from qwen3_5)
            if self.causal_conv1d_implementation == IMPL_TRITON:
                mixed_qkv, _ = self.causal_conv1d_fn(
                    x=mixed_qkv,
                    weight=conv_weight.squeeze(1).transpose(-1, -2).contiguous(),
                    bias=conv_bias,
                    activation=self.activation,
                    cu_seqlens=cu_seqlens,
                )
            elif self.causal_conv1d_implementation == IMPL_TRITON_WITH_TRANSPOSE:
                mixed_qkv, _ = self.causal_conv1d_fn(
                    x=mixed_qkv,
                    weight=conv_weight.squeeze(1),
                    H=2 * local_num_k_heads + local_num_v_heads,
                    bias=conv_bias,
                    activation=self.activation,
                    cu_seqlens=cu_seqlens,
                )
            elif self.causal_conv1d_implementation == IMPL_ASCENDC:
                mixed_qkv = self.causal_conv1d_fn(
                    x=mixed_qkv,
                    weight=conv_weight.squeeze(1),
                    H=2 * local_num_k_heads + local_num_v_heads,
                    bias=conv_bias,
                    activation=self.activation,
                    cu_seqlens=cu_seqlens,
                )[0]
            else:
                mixed_qkv = mixed_qkv.transpose(1, 2)
                mixed_qkv = causal_conv1d_fn(
                    mixed_qkv,
                    conv_weight.squeeze(1),
                    conv_bias,
                    activation=self.activation,
                ).transpose(1, 2)
            if cache_params is not None:
                mixed_qkv = mixed_qkv[:, :seq_len, :] if mixed_qkv.dim() == 3 else mixed_qkv[..., :seq_len]

        if self.causal_conv1d_implementation in (IMPL_TRITON_WITH_TRANSPOSE, IMPL_ASCENDC):
            # NPU kernels return a [b, H, s*d] layout, split per head
            query, key, value = torch.split(
                mixed_qkv,
                [local_num_k_heads, local_num_k_heads, local_num_v_heads],
                dim=1,
            )
        else:
            query, key, value = torch.split(
                mixed_qkv,
                [
                    local_key_dim,
                    local_key_dim,
                    local_value_dim,
                ],
                dim=-1,
            )

            query = query.reshape(query.shape[0], query.shape[1], -1, self.head_k_dim)
            key = key.reshape(key.shape[0], key.shape[1], -1, self.head_k_dim)
            value = value.reshape(value.shape[0], value.shape[1], -1, self.head_v_dim)

        beta = b.sigmoid()
        # If the model is loaded in fp16, without the .float() here, A might be -inf
        if ps.is_ulysses_enable():
            value_head_offset = ulysses_rank * local_num_v_heads
            value_head_slice = slice(value_head_offset, value_head_offset + local_num_v_heads)
            g = -self.A_log[value_head_slice].float().exp() * F.softplus(a.float() + self.dt_bias[value_head_slice])
        else:
            g = -self.A_log.float().exp() * F.softplus(a.float() + self.dt_bias)
        # The AscendC chunk kernel accepts grouped Q/K heads directly.
        use_grouped_qk = self.gdn_implementation == IMPL_ASCENDC and not (
            use_precomputed_states and seq_len == 1
        )
        if self.num_v_heads // self.num_k_heads > 1 and not use_grouped_qk:
            if self.causal_conv1d_implementation in (IMPL_TRITON_WITH_TRANSPOSE, IMPL_ASCENDC):
                query = query.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=1)
                key = key.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=1)
            else:
                query = query.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=2)
                key = key.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=2)

        recurrent_state = cache_params.layers[self.layer_idx].recurrent_states[0] if use_precomputed_states else None
        if use_precomputed_states and seq_len == 1:
            core_attn_out, last_recurrent_state = self.recurrent_gated_delta_rule(
                query,
                key,
                value,
                g=g,
                beta=beta,
                initial_state=recurrent_state,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
            )
        elif self.gdn_implementation in (IMPL_TRITON, IMPL_ASCENDC, IMPL_ASCENDC_LEGACY):
            core_attn_out, last_recurrent_state = self.chunk_gated_delta_rule(
                query,
                key,
                value,
                g=g,
                beta=beta,
                cu_seqlens=cu_seqlens,
                initial_state=recurrent_state,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
                skip_recompute=self.skip_gdn_recompute,
            )
        else:
            core_attn_out, last_recurrent_state = self.chunk_gated_delta_rule(
                query,
                key,
                value,
                g=g,
                beta=beta,
                initial_state=recurrent_state,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
            )

        # Update cache
        if cache_params is not None:
            cache_params.update_recurrent_state(last_recurrent_state, self.layer_idx)

        if ps.is_ulysses_enable():
            core_attn_out = all_to_all(
                core_attn_out,
                ps.get_ulysses_group(),
                scatter_dim=1,
                gather_dim=2,
            )

        # reshape input data into 2D tensor
        core_attn_out = core_attn_out.reshape(-1, self.head_v_dim)
        z = z.reshape(-1, self.head_v_dim)
        core_attn_out = self.norm(core_attn_out, z)
        core_attn_out = core_attn_out.reshape(batch_size, seq_len, -1)

        output = self.out_proj(core_attn_out)
        return output


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(q, k=None, cos=None, sin=None, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors, or only the queries if the keys are not provided.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor if provided.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    rotary_dim = cos.shape[-1]

    # Keep half or full tensor for later concatenation
    q_rope, q_nope = q[..., :rotary_dim], q[..., rotary_dim:]
    # Apply rotary embeddings on the first half or full tensor
    if IS_NPU_AVAILABLE and k is not None and q.dim() == 4:
        # NPU optimized: fused rotary mul instead of separate rotate_half + multiply
        q_rope = torch_npu.npu_rotary_mul(q_rope, cos, sin)
    else:
        q_rope = (q_rope * cos) + (rotate_half(q_rope) * sin)
    # Concatenate back to full tensor
    q_rotated = torch.cat([q_rope, q_nope], dim=-1)

    if k is not None:
        k_rope, k_nope = k[..., :rotary_dim], k[..., rotary_dim:]
        if IS_NPU_AVAILABLE and k.dim() == 4:
            k_rope = torch_npu.npu_rotary_mul(k_rope, cos, sin)
        else:
            k_rope = (k_rope * cos) + (rotate_half(k_rope) * sin)
        k_rotated = torch.cat([k_rope, k_nope], dim=-1)
        return q_rotated, k_rotated
    else:
        return q_rotated


class Qwen4ExpTextQSAIndexer(nn.Module):
    """Select QSA token indices from compressed key blocks."""

    def __init__(self, config: Qwen4ExpTextConfig, layer_idx: int):
        super().__init__()
        self.layer_idx = layer_idx
        self.index_n_heads = config.indexer_n_heads
        self.index_kv_heads = config.indexer_kv_heads
        self.index_head_dim = config.indexer_head_dim
        self.token_budget = config.indexer_budget
        self.compress_ratio = config.indexer_compress_ratio
        self.block_topk = self.token_budget // self.compress_ratio
        self.index_qk_proj = nn.Linear(
            config.hidden_size,
            (self.index_n_heads + self.index_kv_heads) * self.index_head_dim,
            bias=False,
        )
        self.q_layernorm = Qwen4ExpTextRMSNorm(self.index_head_dim, eps=config.rms_norm_eps)
        self.k_layernorm = Qwen4ExpTextRMSNorm(self.index_head_dim, eps=config.rms_norm_eps)
        self.qsa_indexer_implementation = config.qsa_indexer_implementation
        self.qsa_id2mask_implementation = config.qsa_id2mask_implementation

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor,
        past_key_values: Cache | None,
        return_block_ids: bool = False,
    ) -> torch.Tensor:

        if self.qsa_indexer_implementation == IMPL_ASCENDC:
            from mindspeed_mm.fsdp.ops.qsa.ascendc.qsa_indexer import qwen4_exp_qsa_indexer_forward_lightning
            return qwen4_exp_qsa_indexer_forward_lightning(
                self, hidden_states, position_embeddings, attention_mask, past_key_values,
                return_block_ids=return_block_ids,
            )

        batch_size, seq_length, _ = hidden_states.shape
        hidden_shape = (batch_size, seq_length, -1, self.index_head_dim)
        # The cos/sin here are the full positions for the keys, so we need to slice to get only the current positions for the queries
        full_cos, full_sin = position_embeddings
        current_cos, current_sin = full_cos[:, -seq_length:, :], full_sin[:, -seq_length:, :]

        qk = self.index_qk_proj(hidden_states)
        q, token_k = torch.split(
            qk,
            [self.index_n_heads * self.index_head_dim, self.index_kv_heads * self.index_head_dim],
            dim=-1,
        )
        q, raw_keys = q.reshape(*hidden_shape), token_k.reshape(*hidden_shape).squeeze(2)
        q = self.q_layernorm(q)
        q = apply_rotary_pos_emb(q, cos=current_cos, sin=current_sin, unsqueeze_dim=2)

        if past_key_values is not None:
            raw_keys = past_key_values.update_indexer(raw_keys, self.layer_idx)

        # Note that the mask is never None here as we only allow eager and sdpa, and we do not allow sdpa's mask skip
        # It's always 4D with either bool (sdpa) or float (eager) and already gives us the valid indices
        visible_token_indices = attention_mask if attention_mask.dtype == torch.bool else attention_mask == 0
        if return_block_ids:
            visible_token_indices = visible_token_indices.expand(batch_size, -1, -1, -1)

        selected_token_indices = torch.full(
            (batch_size, seq_length, self.block_topk + 1 if return_block_ids else self.token_budget + self.compress_ratio - 1),
            -1,
            dtype=torch.int32,
            device=hidden_states.device,
        )
        for batch_idx in range(batch_size):
            for query_idx in range(seq_length):
                local_visible_indices = torch.nonzero(
                    visible_token_indices[batch_idx, 0, query_idx], as_tuple=False
                ).flatten()
                num_complete_blocks = local_visible_indices.shape[-1] // self.compress_ratio
                # Compute selected tokens
                if num_complete_blocks > 0:
                    block_token_indices = local_visible_indices[: num_complete_blocks * self.compress_ratio].view(
                        num_complete_blocks, self.compress_ratio
                    )

                    key_groups = raw_keys[batch_idx].index_select(0, block_token_indices.flatten())
                    key_groups = key_groups.view(*block_token_indices.shape, self.index_head_dim)
                    pooled_keys = key_groups.float().mean(dim=1).to(raw_keys.dtype)
                    pooled_keys = self.k_layernorm(pooled_keys)
                    group_starts = block_token_indices[:, 0]
                    block_key_states = apply_rotary_pos_emb(
                        pooled_keys.unsqueeze(1),
                        cos=full_cos[batch_idx].index_select(0, group_starts),
                        sin=full_sin[batch_idx].index_select(0, group_starts),
                    ).squeeze(1)

                    scores = torch.matmul(
                        q[batch_idx, query_idx].float(), block_key_states.float().transpose(-1, -2)
                    ).transpose(-1, -2)
                    scores = torch.relu(scores).sum(dim=-1) / math.sqrt(self.index_head_dim)

                    selected_block_indices = scores.topk(min(self.block_topk, num_complete_blocks), dim=0).indices
                    # Remap the indices of the blocks to the indices of individual tokens
                    if not return_block_ids:
                        selected_tokens = block_token_indices.index_select(0, selected_block_indices).flatten()
                else:
                    selected_tokens = torch.tensor([], device=hidden_states.device)
                    selected_block_indices = torch.empty(0, dtype=torch.long, device=hidden_states.device)
                tail = local_visible_indices[num_complete_blocks * self.compress_ratio :]
                if return_block_ids:
                    blocks = selected_block_indices.to(torch.int32)
                    if tail.numel():
                        blocks = torch.cat((blocks, blocks.new_tensor([num_complete_blocks])))
                    selected_token_indices[batch_idx, query_idx, :blocks.numel()] = blocks
                    continue
                selected_tokens = torch.cat([selected_tokens, tail]).to(torch.int32)
                selected_token_indices[batch_idx, query_idx, : selected_tokens.numel()] = selected_tokens

        if return_block_ids:
            return selected_token_indices

        # Create the additive mask to be added to the main causal mask
        kv_length = attention_mask.shape[-1]
        selected_token_mask = torch.zeros(
            (*selected_token_indices.shape[:-1], kv_length + 1), device=attention_mask.device, dtype=torch.bool
        )
        # We absorb all the -1 by scaterring them to the last index that we will drop
        # scatter requires an int64 index; torch.where keeps selected_token_indices' int32 dtype
        scatter_indices = torch.where(selected_token_indices >= 0, selected_token_indices, kv_length).to(torch.int64)
        selected_token_mask = selected_token_mask.scatter(-1, scatter_indices, True)[..., :kv_length].unsqueeze(1)
        # if using eager, convert to float mask
        if attention_mask.is_floating_point():
            min_dtype = torch.finfo(attention_mask.dtype).min
            selected_token_mask = torch.where(selected_token_mask, attention_mask.new_zeros(()), min_dtype)

        return selected_token_mask


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


def qsa_flash_attention_forward(
    module, query, key, value, attention_mask, dropout=0.0, scaling=None, **kwargs,
):
    """BNSD -> BSND using CANN FA/FA-grad with an uncompressed QSA mask.

    Unlike the shared FlashAttention wrapper, this path never substitutes a
    causal template for the per-sample QSA mask. Boolean input means allowed;
    additive input uses zero for allowed and nonzero for masked positions.
    """
    if query.device.type != "npu":
        raise NotImplementedError("QSA flash_attention_2 currently requires NPU")

    ps = get_parallel_state()
    _validate_cp_topology(ps)

    if attention_mask is None or attention_mask.ndim != 4:
        raise ValueError("QSA flash_attention_2 requires the full [B,1,Sq,Skv] attention mask")
    b, h, sq, _ = query.shape
    if key.shape[1] != h:
        if h % key.shape[1] != 0:
            raise ValueError(
                f"QSA key/value heads ({key.shape[1]}) must divide query heads ({h})"
            )
        repeats = h // key.shape[1]
        key = key.repeat_interleave(repeats, dim=1)
        value = value.repeat_interleave(repeats, dim=1)
    if (attention_mask.shape[0] not in (1, b) or attention_mask.shape[1] not in (1, h)
            or attention_mask.shape[2:] != (sq, key.shape[2])):
        raise ValueError("QSA attention mask must match Q/K sequence lengths and batch/heads")

    # CANN uses True for masked positions, the inverse of the QSA boolean mask.
    blocked = ~attention_mask if attention_mask.dtype == torch.bool else attention_mask != 0
    blocked = blocked.contiguous()
    query, key, value = (x.contiguous() for x in (query, key, value))
    skip_recompute = module.training and getattr(module.config, "skip_flash_attn_recompute", False)
    if skip_recompute and dropout:
        raise NotImplementedError("QSA skip_flash_attn_recompute requires attention_dropout=0")
    # inner_precise=2 handles fully masked query rows introduced by padding.
    op_kwargs = dict(
        atten_mask=blocked, scale=scaling if scaling is not None else query.shape[-1] ** -0.5,
        keep_prob=1.0 - dropout, sparse_mode=0, inner_precise=2,
    )
    if skip_recompute:
        from mindspeed_mm.fsdp.ops.flash_attn.skip_recompute_flash_attn import skip_recompute_flash_attention
        output = skip_recompute_flash_attention(query, key, value, h, "BNSD", **op_kwargs)
    else:
        output = torch_npu.npu_fusion_attention(query, key, value, h, "BNSD", **op_kwargs)[0]
    return output.transpose(1, 2).contiguous(), None


class Qwen4ExpTextAttention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen4ExpTextConfig, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True
        self.q_proj = nn.Linear(
            config.hidden_size, config.num_attention_heads * self.head_dim * 2, bias=config.attention_bias
        )
        self.k_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.v_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.o_proj = nn.Linear(
            config.num_attention_heads * self.head_dim, config.hidden_size, bias=config.attention_bias
        )
        self.q_norm = Qwen4ExpTextRMSNorm(self.head_dim, eps=config.rms_norm_eps)
        self.k_norm = Qwen4ExpTextRMSNorm(self.head_dim, eps=config.rms_norm_eps)
        self.indexer = Qwen4ExpTextQSAIndexer(config, layer_idx)
        self.qsa_implementation = config.qsa_implementation

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor,
        past_key_values: Cache | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        ps = get_parallel_state()
        _validate_cp_topology(ps)
        if ps.is_ulysses_enable() and self.qsa_implementation not in (IMPL_FLASH_ATTENTION_2, IMPL_ASCENDC):
            raise NotImplementedError(
                "Qwen4Exp Ulysses CP requires qsa_implementation='flash_attention_2' or 'ascendc'"
            )
        if ps.is_ulysses_enable() and past_key_values is not None:
            raise NotImplementedError("Qwen4Exp QSA Ulysses CP currently supports training prefill only")

        use_generic_sparse = self.qsa_implementation == IMPL_ASCENDC
        local_seq_len = hidden_states.shape[1]
        total_seq_len = get_seq_len("total") if ps.is_ulysses_enable() else local_seq_len
        if ps.is_ulysses_enable():
            if total_seq_len is None:
                raise RuntimeError("set_seq_len('total', ...) must run before Qwen4Exp QSA")
            gather_sizes = cal_split_sizes(total_seq_len, ps.get_ulysses_group_size())
            full_hidden_states = gather_forward_split_backward(
                hidden_states,
                ps.get_ulysses_group(),
                dim=1,
                gather_sizes=gather_sizes,
            )
        else:
            full_hidden_states = hidden_states
        if use_generic_sparse:
            if past_key_values is not None:
                raise NotImplementedError("AscendC QSA currently supports prefill without KV cache only")
            from mindspeed_mm.fsdp.ops.qsa.ascendc.generic_sparse_attention import generic_sparse_attention
            selected_blocks = self.indexer(
                full_hidden_states, position_embeddings, attention_mask, past_key_values, return_block_ids=True
            )
        else:
            selected_token_mask = self.indexer(
                full_hidden_states, position_embeddings, attention_mask, past_key_values
            )
        # Combine the causal/padding mask with the indexer's selected tokens.
        if not use_generic_sparse and attention_mask.is_floating_point():
            attention_mask = attention_mask + selected_token_mask
        elif not use_generic_sparse:
            attention_mask = attention_mask & selected_token_mask

        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)

        query_states, gate = torch.chunk(
            self.q_proj(hidden_states).view(*input_shape, -1, self.head_dim * 2), 2, dim=-1
        )
        gate = gate.reshape(*input_shape, -1)

        query_states = self.q_norm(query_states.view(hidden_shape)).transpose(1, 2)
        key_states = self.k_norm(self.k_proj(hidden_states).view(hidden_shape)).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        # When Ulysses is wider than the native KV head count, repeat GQA heads
        # before A2A so every rank receives the same number of KV heads.  For the
        # usual U <= num_key_value_heads case, AscendC retains native GQA while
        # qsa_flash_attention_forward repeats the post-A2A KV heads instead.
        if ps.is_ulysses_enable():
            ulysses_size = ps.get_ulysses_group_size()
            if self.config.num_attention_heads % ulysses_size != 0:
                raise ValueError(
                    f"QSA query heads ({self.config.num_attention_heads}) must be divisible by "
                    f"ulysses size ({ulysses_size})"
                )
            if ulysses_size > self.config.num_key_value_heads:
                key_states = repeat_kv(key_states, self.num_key_value_groups)
                value_states = repeat_kv(value_states, self.num_key_value_groups)
            elif self.config.num_key_value_heads % ulysses_size != 0:
                raise ValueError(
                    f"QSA KV heads ({self.config.num_key_value_heads}) must be divisible by "
                    f"ulysses size ({ulysses_size}) when Ulysses does not pre-repeat GQA heads"
                )

        if ps.is_ulysses_enable():
            local_position_embeddings = tuple(
                _ulysses_local_slice(x, ps, total_seq_len, dim=1) for x in position_embeddings
            )
        else:
            # The indexer uses all cached positions, while Q/K only contain
            # the tokens in the current call during non-CP decoding.
            local_position_embeddings = tuple(x[:, -local_seq_len:, :] for x in position_embeddings)
        cos, sin = local_position_embeddings
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        if ps.is_ulysses_enable():
            ulysses_group = ps.get_ulysses_group()
            query_states = all_to_all(
                query_states,
                ulysses_group,
                scatter_dim=1,
                gather_dim=2,
                gather_size=total_seq_len,
            )
            key_states = all_to_all(
                key_states,
                ulysses_group,
                scatter_dim=1,
                gather_dim=2,
                gather_size=total_seq_len,
            )
            value_states = all_to_all(
                value_states,
                ulysses_group,
                scatter_dim=1,
                gather_dim=2,
                gather_size=total_seq_len,
            )
            gate = all_to_all(
                gate,
                ulysses_group,
                scatter_dim=2,
                gather_dim=1,
                gather_size=total_seq_len,
            )

        if use_generic_sparse:
            attn_output = generic_sparse_attention(
                query_states, key_states, value_states, selected_blocks,
                block_size=self.indexer.compress_ratio, scale=self.scaling,
                dropout=self.attention_dropout if self.training else 0.0,
            )
            # AscendC returns [B, S_group, Hq_local * D]. Keep the full
            # sequence until the common gate and reverse Ulysses exchange.
            attn_weights = None
        else:
            if past_key_values is not None:
                key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx)

            # Select QSA independently of the vision/global attention backend.
            if self.qsa_implementation == IMPL_FLASH_ATTENTION_2:
                attention_interface = qsa_flash_attention_forward
            else:
                attention_interface = eager_attention_forward
                if attention_mask.dtype == torch.bool:
                    attention_mask = torch.where(attention_mask, 0.0, torch.finfo(query_states.dtype).min).to(
                        query_states.dtype
                    )

            attn_output, attn_weights = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask,
                dropout=0.0 if not self.training else self.attention_dropout,
                scaling=self.scaling,
                **kwargs,
            )

        # After Ulysses A2A both tensors are full-sequence/local-head. Apply the
        # per-head gate before the reverse exchange, while their sequence/head
        # layouts still match.
        if ps.is_ulysses_enable():
            attn_output = attn_output.reshape(attn_output.shape[0], attn_output.shape[1], -1)
            attn_output = attn_output * torch.sigmoid(gate)
            attn_output = attn_output.view(
                attn_output.shape[0], attn_output.shape[1], -1, self.head_dim
            )
            attn_output = all_to_all(
                attn_output,
                ps.get_ulysses_group(),
                scatter_dim=1,
                gather_dim=2,
            )
        else:
            attn_output = attn_output.reshape(*input_shape, -1).contiguous()
            attn_output = attn_output * torch.sigmoid(gate)

        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights


class Qwen4ExpTextMLP(nn.Module):
    def __init__(self, config, intermediate_size=None):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size if intermediate_size is None else intermediate_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        down_proj = self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))
        return down_proj


@use_experts_implementation
class Qwen4ExpTextExperts(nn.Module):
    """Collection of expert weights stored as 3D tensors."""

    def __init__(self, config):
        super().__init__()
        self.num_experts = config.num_experts
        self.hidden_dim = config.hidden_size
        self.intermediate_dim = config.moe_intermediate_size
        self.gate_up_proj = nn.Parameter(torch.empty(self.num_experts, 2 * self.intermediate_dim, self.hidden_dim))
        self.down_proj = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim, self.intermediate_dim))
        self.act_fn = ACT2FN[config.hidden_act]
        self.use_grouped_expert_matmul = getattr(config, "use_grouped_expert_matmul", False)
        if self.use_grouped_expert_matmul and IS_NPU_AVAILABLE:
            print_rank(logger.info, "Qwen4ExpTextExperts use NPU fused ops")

        # EP load balancing (hot-expert duplication), the planner
        # is weight-layout agnostic (it works on expert IDs), so it is safe to build here even
        # though ep_forward feeds the dispatcher transposed [E, in, out] views of the stored
        # [E, out, in] weights.
        ps = get_parallel_state()
        self.enable_ep_balance = getattr(config, "enable_ep_balance", False) and ps.is_ep_enable()
        if self.enable_ep_balance:
            from mindspeed_mm.fsdp.distributed.expert_parallel.ep_balance.ep_balance_strategy import EPBalanceStrategy
            self.ep_balance_strategy = EPBalanceStrategy(
                ep_group = ps.get_ep_group(),
                num_experts = self.num_experts,
                max_dup_experts_num = getattr(config, "max_dup_experts_num", 2),
            )
            def hook_fn(*args, **kwargs):
                self.ep_balance_strategy.planner.pop_plan_cache()
            self.register_full_backward_hook(hook_fn)
        self.skip_moe_pad_tokens = config.skip_moe_pad_tokens

    def extra_repr(self) -> str:
        return (
            f"(gate_up_proj): Parameter(num_experts={self.num_experts}, "
            f"hidden_dim={self.hidden_dim}, intermediate_dim={2 * self.intermediate_dim})\n"
            f"(down_proj): Parameter(num_experts={self.num_experts}, "
            f"intermediate_dim={self.intermediate_dim}, hidden_dim={self.hidden_dim})"
        )

    def forward(
        self,
        hidden_states: torch.Tensor,
        top_k_index: torch.Tensor,
        top_k_weights: torch.Tensor,
    ) -> torch.Tensor:
        if self.use_grouped_expert_matmul and IS_NPU_AVAILABLE:
            from mindspeed_mm.models.common.gmm import npu_group_gemm

            permuted_hidden_states, row_ids_map = torch_npu.npu_moe_token_permute(
                hidden_states, top_k_index.to(torch.int32)
            )
            tokens_per_expert = torch.histc(top_k_index, bins=self.num_experts, min=0, max=self.num_experts)
            # Modification: npu_group_gemm computes x @ W and expects [E, in, out] weight layout, but this
            # module stores weights nn.Linear-style [E, out, in] (see the eager fallback below, which uses
            # F.linear). Feed transposed views — autograd maps the produced grads back onto the stored
            # layout through the transpose nodes.
            gate_up_proj = self.gate_up_proj.transpose(1, 2)
            down_proj = self.down_proj.transpose(1, 2)
            intermediate_hidden_states = npu_group_gemm(permuted_hidden_states, gate_up_proj, tokens_per_expert)
            intermediate_activations = torch_npu.npu_swiglu(intermediate_hidden_states, dim=-1)
            output = npu_group_gemm(intermediate_activations, down_proj, tokens_per_expert)
            final_hidden_states = torch_npu.npu_moe_token_unpermute(output, row_ids_map, probs=top_k_weights)
            return final_hidden_states

        final_hidden_states = torch.zeros_like(hidden_states)
        with torch.no_grad():
            expert_mask = torch.nn.functional.one_hot(top_k_index, num_classes=self.num_experts + 1)
            expert_mask = expert_mask.permute(2, 1, 0)
            expert_hit = torch.greater(expert_mask.sum(dim=(-1, -2)), 0).nonzero()

        for expert_idx in expert_hit:
            expert_idx = expert_idx[0]
            if expert_idx == self.num_experts:
                continue
            top_k_pos, token_idx = torch.where(expert_mask[expert_idx])
            current_state = hidden_states[token_idx]
            gate, up = nn.functional.linear(current_state, self.gate_up_proj[expert_idx]).chunk(2, dim=-1)
            current_hidden_states = self.act_fn(gate) * up
            current_hidden_states = nn.functional.linear(current_hidden_states, self.down_proj[expert_idx])
            current_hidden_states = current_hidden_states * top_k_weights[token_idx, top_k_pos, None]
            final_hidden_states.index_add_(0, token_idx, current_hidden_states.to(final_hidden_states.dtype))

        return final_hidden_states

    def ep_forward(
        self,
        hidden_states: torch.Tensor,
        top_k_index: torch.Tensor,
        top_k_weights: torch.Tensor,
        ep_group,
        ep_plan,
        **kwargs,
    ) -> torch.Tensor:
        """Expert-parallel entry injected by ``expert_parallelize_modules``: tokens are dispatched to
        the expert owners by the plan's dispatcher instead of the expert weights being gathered.

        Layout note: this module stores weights nn.Linear-style ``[E, out, in]`` while the EP
        dispatchers expect ``[E, in, out]``
        ``fc1_weight``/``fc2_weight``; pass transposed views so produced grads flow back onto the
        stored layout. ``expert_parallel_size`` for this model must divide ``num_experts`` (checked
        in ``dispatch_preprocess``). EP load balancing (``enable_ep_balance``, YAML
        ``features.enable_ep_balance``) is supported with ``alltoall`` via ``EPBalanceStrategy``; the gradient
        accumulation hooks must be registered on the SAME transposed views handed to the
        dispatcher, because their ``add_dup_experts_grad`` reshape assumes the dispatcher-side
        ``[E, in, out]`` layout.
        """
        gate_up_proj = self.gate_up_proj.to_local() if isinstance(self.gate_up_proj, DTensor) else self.gate_up_proj
        down_proj = self.down_proj.to_local() if isinstance(self.down_proj, DTensor) else self.down_proj
        fc1_weight = gate_up_proj.transpose(1, 2)
        fc2_weight = down_proj.transpose(1, 2)

        from mindspeed_mm.fsdp.distributed.expert_parallel.ep_dispatcher import (
            ep_allgather_forward,
            ep_forward,
            ep_mc2_forward,
        )
        from mindspeed_mm.fsdp.distributed.expert_parallel.ep_chunkmoe import ep_chunkmoe_forward

        ep_dispatcher_dict = {
            "alltoall": ep_forward,
            "mc2": ep_mc2_forward,
            "allgather": ep_allgather_forward,
            "chunkmoe": ep_chunkmoe_forward,
        }
        if ep_plan.dispatcher not in ep_dispatcher_dict:
            raise NotImplementedError(
                f"ep_plan.dispatcher='{ep_plan.dispatcher}' is not supported by Qwen4ExpTextExperts."
            )

        if self.enable_ep_balance:
            if ep_plan.dispatcher != "alltoall":
                raise NotImplementedError("EP load balancing strategy currently only supports alltoall dispatch.")
            self.ep_balance_strategy.executor.register_backward_dup_experts_grad_acc_hook(fc1_weight, name="fc1")
            self.ep_balance_strategy.executor.register_backward_dup_experts_grad_acc_hook(fc2_weight, name="fc2")

        if ep_plan.dispatcher == "chunkmoe" and self.skip_moe_pad_tokens:
            raise NotImplementedError("chunkmoe dispatch does not support skip_moe_pad_tokens yet.")

        dispatcher_kwargs = dict(
            fc1_weight=fc1_weight,
            fc2_weight=fc2_weight,
            ep_group=ep_group,
            fused=ep_plan.use_npu_fused_ops,
            ep_balance_strategy=self.ep_balance_strategy if self.enable_ep_balance else None,
            seq_mask=kwargs.get("seq_mask", None),
            skip_moe_pad_tokens=self.skip_moe_pad_tokens,
        )
        if ep_plan.dispatcher == "chunkmoe":
            dispatcher_kwargs["ep_plan"] = ep_plan

        hidden_states = ep_dispatcher_dict[ep_plan.dispatcher](
            self.num_experts,
            top_k_weights,
            top_k_index,
            hidden_states,
            **dispatcher_kwargs,
        )
        return hidden_states


class Qwen4ExpTextTopKRouter(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.top_k = config.num_experts_per_tok
        self.num_experts = config.num_experts
        self.norm_topk_prob = config.norm_topk_prob
        self.hidden_dim = config.hidden_size
        self.weight = nn.Parameter(torch.zeros(self.num_experts, self.hidden_dim))

    def forward(self, hidden_states):
        hidden_states = hidden_states.reshape(-1, self.hidden_dim)
        router_logits = F.linear(hidden_states, self.weight)  # (seq_len, num_experts)
        router_probs = torch.nn.functional.softmax(router_logits, dtype=torch.float, dim=-1)
        router_top_value, router_indices = torch.topk(router_probs, self.top_k, dim=-1)  # (seq_len, top_k)
        if self.norm_topk_prob:
            router_top_value /= router_top_value.sum(dim=-1, keepdim=True)
        router_top_value = router_top_value.to(router_logits.dtype)
        router_scores = router_top_value
        return router_logits, router_scores, router_indices


class Qwen4ExpTextSparseMoeBlock(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.gate = Qwen4ExpTextTopKRouter(config)
        self.experts = Qwen4ExpTextExperts(config)
        self.shared_expert = Qwen4ExpTextMLP(config, intermediate_size=config.shared_expert_intermediate_size)
        self.shared_expert_gate = torch.nn.Linear(config.hidden_size, 1, bias=False)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        batch_size, sequence_length, hidden_dim = hidden_states.shape
        hidden_states_reshaped = hidden_states.view(-1, hidden_dim)
        shared_expert_output = self.shared_expert(hidden_states_reshaped)
        _, routing_weights, selected_experts = self.gate(hidden_states_reshaped)
        expert_output = self.experts(hidden_states_reshaped, selected_experts, routing_weights)

        shared_expert_output = F.sigmoid(self.shared_expert_gate(hidden_states_reshaped)) * shared_expert_output

        expert_output = expert_output + shared_expert_output
        expert_output = expert_output.reshape(batch_size, sequence_length, hidden_dim)
        return expert_output


class Qwen4ExpTextGatedResidual(nn.Module):
    def __init__(self, config: Qwen4ExpTextConfig, use_combine: bool = True):
        super().__init__()
        self.qhc_implementation = config.qhc_implementation
        self.hc_count = config.hc_count
        self.hidden_size = config.hidden_size
        hc_hidden_size = self.hc_count * self.hidden_size
        self.hc_norm = Qwen4ExpTextRMSNorm(hc_hidden_size, group_size=self.hidden_size, eps=config.rms_norm_eps)
        self.input_mix_weight_down = nn.Linear(hc_hidden_size, config.hc_lowrank, bias=False)
        self.input_mix_weight_up = nn.Linear(config.hc_lowrank, hc_hidden_size, bias=False)
        self.block_inject_weight = nn.Linear(hc_hidden_size, self.hc_count, bias=False) if use_combine else None

    def forward(
        self, hyper_input: torch.Tensor
    ) -> torch.Tensor | tuple[torch.Tensor, tuple[torch.Tensor, torch.Tensor]]:
        if hyper_input.shape[-1] != self.hc_count * self.hidden_size:
            raise ValueError(
                f"Expected {self.hc_count * self.hidden_size} hyper-connection features, got {hyper_input.shape[-1]}."
            )
        if self.qhc_implementation == IMPL_ASCENDC:
            from mindspeed_mm.fsdp.ops.qhc.qhc_ascendc import qhc_ascendc

            output = qhc_ascendc(
                hyper_input,
                self.input_mix_weight_down.weight,
                self.input_mix_weight_up.weight,
                w_gate=self.block_inject_weight.weight if self.block_inject_weight is not None else None,
                # The kernel applies 1 + gamma internally and requires FP32 gamma.
                gamma=self.hc_norm.weight.float(),
                channels=self.hc_count,
                eps=self.hc_norm.eps,
            )
            if self.block_inject_weight is None:
                return output
            mixed_input, injection_weights = output
            return mixed_input, hyper_input, injection_weights

        elif self.qhc_implementation == IMPL_TRITON:
            from mindspeed_mm.fsdp.ops.qhc.qhc_triton import qhc_triton
            result = qhc_triton(
                hyper_input,
                self.hc_norm.weight,
                self.input_mix_weight_down.weight,
                self.input_mix_weight_up.weight,
                self.block_inject_weight.weight
                if self.block_inject_weight is not None
                else None,
                self.hc_count,
                self.hidden_size,
                self.hc_norm.eps,
            )
            if self.block_inject_weight is None:
                return result
            mixed, injection = result
            return mixed, hyper_input, injection

        hyper_input_normed = self.hc_norm(hyper_input)
        input_mix_weight = F.silu(self.input_mix_weight_down(hyper_input_normed) / self.hc_count)
        input_mix_weight = torch.sigmoid(self.input_mix_weight_up(input_mix_weight))
        input_mix_weight = input_mix_weight.unflatten(-1, (self.hc_count, self.hidden_size))
        mixed_input = (input_mix_weight * hyper_input_normed.unflatten(-1, (self.hc_count, self.hidden_size))).mean(
            dim=-2
        )
        if self.block_inject_weight is None:
            return mixed_input
        injection_weights = 2 * torch.sigmoid(self.block_inject_weight(hyper_input_normed) / self.hc_count)
        return mixed_input, hyper_input, injection_weights


_MASK64 = (1 << 64) - 1
_SPLITMIX_GAMMA = 0x9E3779B97F4A7C15
_SPLITMIX_M1 = 0xBF58476D1CE4E5B9
_SPLITMIX_M2 = 0x94D049BB133111EB
_PRIME_1 = 10007


def _splitmix64(value: int) -> int:
    value = (value + _SPLITMIX_GAMMA) & _MASK64
    value = ((value ^ (value >> 30)) * _SPLITMIX_M1) & _MASK64
    value = ((value ^ (value >> 27)) * _SPLITMIX_M2) & _MASK64
    return (value ^ (value >> 31)) & _MASK64


def _build_layer_multipliers(unigram_vocab_size, ngram_size, ple_layer_index, seed: int) -> torch.Tensor:
    max_long = (1 << 63) - 1
    multiplier_max = max_long // max(unigram_vocab_size, 1)
    half_bound = max(1, multiplier_max // 2)
    base_seed = seed + _PRIME_1 * ple_layer_index
    multipliers = []
    for index in range(ngram_size):
        value = (base_seed + _SPLITMIX_GAMMA * (index + 1)) & _MASK64
        multipliers.append(2 * (_splitmix64(value) % half_bound) + 1)
    return torch.tensor(multipliers, dtype=torch.long)


def _is_prime(value: int) -> bool:
    if value < 2:
        return False
    if value % 2 == 0:
        return value == 2
    for divisor in range(3, math.isqrt(value) + 1, 2):
        if value % divisor == 0:
            return False
    return True


def _find_nth_prime_after(start: int, count: int) -> int:
    prime = start
    for _ in range(count):
        prime += 1
        while not _is_prime(prime):
            prime += 1
    return prime


class Qwen4ExpTextNGramEmbedding(nn.Module):
    def __init__(self, config: Qwen4ExpTextConfig, embedding_dim: int, layer_idx: int, ple_layer_index: int = 0):
        super().__init__()
        self.layer_idx = layer_idx
        self.ngram_size = config.ngram_size
        self.context_len = self.ngram_size - 1
        self.heads_per_ngram = config.heads_per_ngram
        self.ngram_heads = (self.ngram_size - 1) * self.heads_per_ngram
        self.ple_layer_index = ple_layer_index
        self.unigram_vocab_size = config.vocab_size
        ngram_vocab_size_base_override = os.environ.get("NGRAM_VOCAB_SIZE_BASE", "").strip()
        if ngram_vocab_size_base_override:
            self.ngram_vocab_size_base = int(ngram_vocab_size_base_override)
            if self.ngram_vocab_size_base <= 0:
                raise ValueError("NGRAM_VOCAB_SIZE_BASE must be a positive integer.")
        else:
            self.ngram_vocab_size_base = config.ngram_vocab_size_base
        head_dim_per_ngram = embedding_dim // self.ngram_heads
        self.seed = config.seed
        # CODEPATH: @ArthurZucker fix flagging for no reason here
        self.eos_token_id = config.eos_token_id[0] if isinstance(config.eos_token_id, list) else config.eos_token_id

        self.head_vocab_sizes = []
        self.head_offsets = []
        self.total_vocab_size = 0
        for head_idx in range(self.ngram_heads):
            global_head_idx = self.ple_layer_index * self.ngram_heads + head_idx
            size = _find_nth_prime_after(self.ngram_vocab_size_base - 1, global_head_idx + 1)
            self.head_vocab_sizes.append(size)
            self.head_offsets.append(self.total_vocab_size)
            self.total_vocab_size += size

        self.layer_multipliers = nn.Buffer(
            _build_layer_multipliers(self.unigram_vocab_size, self.ngram_size, self.ple_layer_index, self.seed)
        )
        self.ngram_heads_vocab_sizes = nn.Buffer(torch.tensor(self.head_vocab_sizes, dtype=torch.long))
        self.ngram_heads_offsets = nn.Buffer(torch.tensor(self.head_offsets, dtype=torch.long))
        ngram_vocab_divisor = config.make_ngram_vocab_size_divisible_by
        padded_vocab_size = math.ceil(self.total_vocab_size / ngram_vocab_divisor) * ngram_vocab_divisor
        self.ngram_embedding = nn.Embedding(padded_vocab_size, head_dim_per_ngram)

    def _shift_right_ignore_eos(self, token_ids: torch.Tensor, shift: int) -> torch.Tensor:
        if shift == 0:
            return token_ids
        batch_size, seq_len = token_ids.shape
        positions = torch.arange(seq_len, device=token_ids.device, dtype=torch.long)
        eos_positions = torch.where(token_ids == self.eos_token_id, positions, -1)
        previous_eos_inclusive = torch.cummax(eos_positions, dim=1).values
        previous_eos = torch.cat([eos_positions.new_full((batch_size, 1), -1), previous_eos_inclusive[:, :-1]], dim=1)
        segment_start = previous_eos + 1
        position_in_segment = positions.unsqueeze(0) - segment_start
        source_positions = positions - shift
        gather_positions = source_positions.clamp_min(0).unsqueeze(0).expand(batch_size, -1)
        shifted = token_ids.gather(dim=1, index=gather_positions)
        valid = (position_in_segment >= shift) & (source_positions.unsqueeze(0) >= 0)
        return torch.where(valid, shifted, token_ids.new_full((), self.eos_token_id))

    def _compute_ngram_ids(self, input_ids: torch.Tensor, past_key_values: Cache | None) -> torch.Tensor:
        """compute ngram ids [batch, seq_len, ngram_heads] from input_ids [batch, seq_len] and past_key_values
        """
        input_ids = input_ids.long()
        # This is a trick to store the previous N=self.context_len `input_ids` - indeed the manipulations are identical to storing
        # a past conv_state, so we can use an additional conv_states inside the Cache for it
        if past_key_values is not None and past_key_values.has_previous_state(self.layer_idx, state_idx=2):
            previous_context = past_key_values.layers[self.layer_idx].conv_states[2].clone()
        else:
            previous_context = input_ids.new_full((input_ids.shape[0], self.context_len), self.eos_token_id)
        # Store the current input_ids for the next forward
        if past_key_values is not None:
            input_ids_to_cache = input_ids
            # In the case where `input_ids` would be smaller than `self.context_len`, the `update_conv_state` will pad with zeros, whereas
            # here we want to pad with eos, so we do it explicitly
            if (
                not past_key_values.has_previous_state(self.layer_idx, state_idx=2)
                and input_ids.shape[1] < self.context_len
            ):
                input_ids_to_cache = torch.nn.functional.pad(
                    input_ids_to_cache, (self.context_len - input_ids.shape[1], 0), value=self.eos_token_id
                )
            _ = past_key_values.update_conv_state(
                input_ids_to_cache, self.layer_idx, state_idx=2, conv_kernel_size=self.context_len
            )

        # Get full token history
        token_history = torch.cat([previous_context, input_ids], dim=-1)
        shifted_tokens = [self._shift_right_ignore_eos(token_history, shift) for shift in range(self.ngram_size)]

        blocks = []
        for ngram in range(2, self.ngram_size + 1):
            start_idx = (ngram - 2) * self.heads_per_ngram
            end_idx = start_idx + self.heads_per_ngram
            mixed_ids = shifted_tokens[0] * self.layer_multipliers[0]
            for position in range(1, ngram):
                mixed_ids = torch.bitwise_xor(
                    mixed_ids,
                    shifted_tokens[position] * self.layer_multipliers[position],
                )
            head_vocab_sizes = self.ngram_heads_vocab_sizes[start_idx:end_idx]
            head_offsets = self.ngram_heads_offsets[start_idx:end_idx]
            ngram_ids = torch.remainder(mixed_ids.unsqueeze(-1), head_vocab_sizes.view(1, 1, -1))
            blocks.append(ngram_ids + head_offsets.view(1, 1, -1))

        ngram_ids = torch.cat(blocks, dim=-1)[:, -input_ids.shape[1] :]
        ps = get_parallel_state()
        _validate_cp_topology(ps)
        if ps.is_ulysses_enable():
            if past_key_values is not None:
                raise NotImplementedError("Qwen4Exp PLE Ulysses CP currently supports training prefill only")
            # Hash the full token history first: local input_ids would replace
            # the previous rank's context with EOS at every shard boundary.
            ngram_ids = _ulysses_local_slice(ngram_ids, ps, input_ids.shape[1], dim=1)
        return ngram_ids

    def forward(self, input_ids: torch.Tensor, past_key_values: Cache | None) -> torch.Tensor:
        ngram_ids = self._compute_ngram_ids(input_ids, past_key_values)
        # We need explicit device placement here, as the embedding may be skipped from device_map completely (we just need to be
        # careful in the case of offloading to disk)
        execution_device = (
            self.ngram_embedding.weight.device if self.ngram_embedding.weight.device.type != "meta" else None
        )
        return self.ngram_embedding(ngram_ids.to(execution_device)).to(ngram_ids.device).flatten(-2)

    def vp_forward(
        self,
        input_ids: torch.Tensor,
        past_key_values: Cache | None,
        vocab_group=None,
        vocab_plan=None,
    ) -> torch.Tensor:
        """Vocab-parallel lookup injected by `vocab_parallelize_modules` (see `vocab_plan`).

        The model either leaves this as the module's ``forward``, or calls the same function ahead of
        the consuming layer (see VocabPlanConfig.prefetch). Because only `input_ids` decides which
        rows are needed, the earlier call lets recomputation reuse its result instead of looking the
        rows up again.
        """
        return self.vp_resolve(self.vp_prepare(input_ids, past_key_values, vocab_group, vocab_plan))

    def vp_prepare(self, input_ids: torch.Tensor, past_key_values: Cache | None, vocab_group=None,
                   vocab_plan=None):
        """Ids plus the first half of the lookup: route them, fetch the rows, start the copy.

        Called ahead of the decoder layers, so the host-to-device copy can run under the layers in
        between; the layer finishes it through :meth:`vp_finish` (see VocabPlanConfig.prefetch_split).
        """
        from mindspeed_mm.fsdp.distributed.vocab_parallel.vocab_dispatcher import get_vocab_split_dispatcher

        if vocab_plan is None:
            raise RuntimeError("vp_prepare requires vocab_plan; it is injected by vocab_parallelize_modules.")
        ngram_ids = self._compute_ngram_ids(input_ids, past_key_values)
        prepare, _ = get_vocab_split_dispatcher(vocab_plan.dispatcher)
        return prepare(self.ngram_embedding, ngram_ids, vocab_group, vocab_plan)

    def vp_finish(self, pending) -> torch.Tensor:
        """Second half of a split lookup: cast, embedding all-to-all, unpermute, flatten."""
        from mindspeed_mm.fsdp.distributed.vocab_parallel.vocab_dispatcher import get_vocab_split_dispatcher

        _, finish = get_vocab_split_dispatcher(pending.dispatcher)
        return finish(self.ngram_embedding, pending).flatten(-2)

    def vp_resolve(self, prefetched):
        """Complete a prefetched lookup: a ready tensor when it was not split, or the pending one."""
        from mindspeed_mm.fsdp.distributed.vocab_parallel.vocab_dispatcher import PendingLookup

        if isinstance(prefetched, PendingLookup):
            # Hold the record (and the rows it carries) past the forward: the recomputation pass reads
            # it again from inside the backward, while the model's own dictionary is gone by then.
            self._vp_pending = prefetched
            return self.vp_finish(prefetched)
        return prefetched

    @staticmethod
    def vp_batch_size(prefetched) -> int:
        """Batch size a prefetched lookup was computed for (both shapes carry it)."""
        from mindspeed_mm.fsdp.distributed.vocab_parallel.vocab_dispatcher import PendingLookup

        return prefetched.batch_size if isinstance(prefetched, PendingLookup) else prefetched.shape[0]


class Qwen4ExpTextPLELayer(nn.Module):
    """Inject hashed n-gram features into every hyper-connection stream.

    PLE projects each token's concatenated n-gram embedding to a shared value and one key per residual stream. The
    normalized stream activations gate those values, then a dilated depthwise convolution adds local lexical context.
    The returned tensor has shape `(batch_size, sequence_length, hc_count * hidden_size)`.
    """

    def __init__(self, config: Qwen4ExpTextConfig, layer_idx: int, ple_layer_index: int):
        super().__init__()
        self.layer_idx = layer_idx
        self.hidden_size = config.hidden_size
        self.hc_count = config.hc_count
        ple_embed_dim = config.ple_embed_dim
        hc_hidden_size = self.hidden_size * self.hc_count
        self.ple_embedding = Qwen4ExpTextNGramEmbedding(config, ple_embed_dim, layer_idx, ple_layer_index)
        conv_kernel_size = config.ple_conv_kernel_size
        conv_dilation = config.ngram_size
        self.short_conv_state_len = (conv_kernel_size - 1) * conv_dilation
        self.key_proj = nn.Linear(ple_embed_dim, hc_hidden_size, bias=False)
        self.value_proj = nn.Linear(ple_embed_dim, self.hidden_size, bias=False)
        self.norm_key = Qwen4ExpTextRMSNorm(hc_hidden_size, group_size=self.hidden_size, eps=config.rms_norm_eps)
        self.norm_query = Qwen4ExpTextRMSNorm(hc_hidden_size, group_size=self.hidden_size, eps=config.rms_norm_eps)
        self.norm_conv = Qwen4ExpTextRMSNorm(hc_hidden_size, group_size=self.hidden_size, eps=config.rms_norm_eps)
        self.conv1d = nn.Conv1d(
            hc_hidden_size,
            hc_hidden_size,
            kernel_size=conv_kernel_size,
            groups=hc_hidden_size,
            dilation=conv_dilation,
            bias=False,
        )

    def _short_conv(self, hidden_states: torch.Tensor, past_key_values: Cache | None) -> torch.Tensor:
        ps = get_parallel_state()
        _validate_cp_topology(ps)
        if ps.is_ulysses_enable():
            if past_key_values is not None:
                raise NotImplementedError("Qwen4Exp PLE Ulysses CP currently supports training prefill only")
            # Exchange channels for complete sequences so the dilated causal
            # convolution retains its left context across sequence shards.
            hidden_states = all_to_all(
                hidden_states, ps.get_ulysses_group(), scatter_dim=2, gather_dim=1,
                gather_size=get_seq_len("total"),
            )
        seq_len = hidden_states.shape[1]
        hidden_states = hidden_states.transpose(1, 2)

        if past_key_values is not None:
            hidden_states = past_key_values.update_conv_state(
                hidden_states, self.layer_idx, state_idx=1, conv_kernel_size=self.short_conv_state_len
            )

        # We always pad and slice due to the dilation in the conv, to make sure we have enough states
        hidden_states = F.pad(hidden_states, (self.short_conv_state_len, 0))
        hidden_states = hidden_states[..., -(self.short_conv_state_len + seq_len) :]

        # We cannot use the usual functions/kernels here for the short conv as the conv1d has dilation
        if ps.is_ulysses_enable():
            weight = _ulysses_local_slice(self.conv1d.weight, ps, self.conv1d.out_channels, dim=0)
            hidden_states = F.silu(F.conv1d(
                hidden_states, weight, dilation=self.conv1d.dilation, groups=weight.shape[0],
            ))
        else:
            hidden_states = F.silu(self.conv1d(hidden_states))

        hidden_states = hidden_states.transpose(1, 2)
        if ps.is_ulysses_enable():
            hidden_states = all_to_all(
                hidden_states, ps.get_ulysses_group(), scatter_dim=1, gather_dim=2,
                gather_size=self.conv1d.out_channels,
            )
        return hidden_states

    def forward(
        self,
        hidden_states: torch.Tensor,
        input_ids: torch.Tensor,
        past_key_values: Cache | None,
        conv_mask: torch.Tensor | None = None,
        prefetched: object | None = None,
    ) -> torch.Tensor:
        # A prefetched tensor holds the whole batch; a chunked micro-batch (chunk_mbs) would need its
        # own slice, so look this chunk's rows up instead of using the wrong ones. Such a mismatch means
        # the whole-batch prefetch can never be consumed, so drop the prefetch of this table: the model
        # only calls it while `_vp_prefetch` is set, and one lookup of the whole batch per step would
        # otherwise be computed and thrown away for every chunk above.
        # `prefetched` is either a ready tensor (unsplit prefetch) or a pending lookup whose copy is
        # still in flight; `vp_batch_size` and `vp_resolve` handle both, and the first thing resolve
        # does for the pending case is wait for that copy.
        if prefetched is not None and self.ple_embedding.vp_batch_size(prefetched) == input_ids.shape[0]:
            embeddings = self.ple_embedding.vp_resolve(prefetched)
        else:
            if prefetched is not None:
                self.ple_embedding._vp_prefetch = None
                print_rank(
                    logger.info,
                    f"[Vocabulary Parallel] prefetch off for layers.{self.layer_idx}.ple.ple_embedding: "
                    f"the layer receives a batch of {input_ids.shape[0]} while the prefetch computed "
                    f"{self.ple_embedding.vp_batch_size(prefetched)} rows (chunk_mbs slices the batch in "
                    f"between), so the lookup stays inside the layer from now on",
                )
            embeddings = self.ple_embedding(input_ids, past_key_values)
        key_normed = self.norm_key(self.key_proj(embeddings)).unflatten(-1, (self.hc_count, self.hidden_size))
        value = self.value_proj(embeddings)
        query_normed = self.norm_query(hidden_states).unflatten(-1, (self.hc_count, self.hidden_size))
        gate = (key_normed * query_normed).sum(dim=-1, keepdim=True) / math.sqrt(self.hidden_size)
        gate = gate.abs().clamp_min(1e-6).sqrt() * gate.sign()
        gated_value = torch.sigmoid(gate) * value.unsqueeze(-2)
        gated_value_normed = self.norm_conv(gated_value.flatten(-2))
        gated_value = gated_value.flatten(-2)
        if conv_mask is not None:
            gated_value = apply_mask_to_padding_states(gated_value, conv_mask)
            gated_value_normed = apply_mask_to_padding_states(gated_value_normed, conv_mask)
        output = gated_value + self._short_conv(gated_value_normed, past_key_values)
        return output


class Qwen4ExpTextDecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Qwen4ExpTextConfig, layer_idx: int):
        super().__init__()
        self.layer_type = config.layer_types[layer_idx]
        if self.layer_type == "linear_attention":
            self.linear_attn = Qwen4ExpTextGatedDeltaNet(config, layer_idx)
        else:
            self.self_attn = Qwen4ExpTextAttention(config, layer_idx)
        self.mlp = Qwen4ExpTextSparseMoeBlock(config)
        # CODEPATH: @ArthurZucker fix flagging for no reason here
        ple_layer_index = config.ple_layer_ids.index(layer_idx + 1) if layer_idx + 1 in config.ple_layer_ids else None
        self.ple = Qwen4ExpTextPLELayer(config, layer_idx, ple_layer_index) if ple_layer_index is not None else None
        self.attn_hyper_connection = Qwen4ExpTextGatedResidual(config)
        self.mlp_hyper_connection = Qwen4ExpTextGatedResidual(config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor | None = None,
        conv_mask: torch.Tensor | None = None,
        past_key_values: Cache | None = None,
        ple_input_ids: torch.LongTensor | None = None,
        ple_prefetched: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.FloatTensor:
        if self.ple is not None:
            hidden_states = hidden_states + self.ple(
                hidden_states, ple_input_ids, past_key_values, conv_mask=conv_mask, prefetched=ple_prefetched
            )

        hidden_states, hyper_input, injection_weights = self.attn_hyper_connection(hidden_states)
        if self.layer_type == "linear_attention":
            hidden_states = self.linear_attn(
                hidden_states, cache_params=past_key_values, attention_mask=conv_mask, **kwargs
            )
        else:
            hidden_states, _ = self.self_attn(
                hidden_states,
                position_embeddings,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                **kwargs,
            )

        injection = hidden_states.unsqueeze(-2) * injection_weights.unsqueeze(-1)
        hidden_states = hyper_input + injection.flatten(-2)

        hidden_states, hyper_input, injection_weights = self.mlp_hyper_connection(hidden_states)
        hidden_states = self.mlp(hidden_states)

        injection = hidden_states.unsqueeze(-2) * injection_weights.unsqueeze(-1)
        hidden_states = hyper_input + injection.flatten(-2)
        return hidden_states


@auto_docstring
class Qwen4ExpPreTrainedModel(PreTrainedModel):
    config: Qwen4ExpConfig
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = None  # will be set on text and vision separately
    _skip_keys_device_placement = ["past_key_values"]
    _supports_flash_attn = True
    _supports_sdpa = True
    _keys_to_ignore_on_load_unexpected = [r"^mtp.*"]
    _can_record_outputs = None  # will be set on text and vision separately
    _is_stateful = True
    _can_compile_fullgraph = True
    _supports_flex_attn = False
    # This embedding is so big (~95 GiB) that on most hardware setups, we must completely skip it from the `device_map` as otherwise
    # it will lead to full model offloading, and memory OOM as accelerate tries to put cpu-offloaded params back on accelerator
    # during forward. Note that if it fits on accelerator (e.g. huge B200 gpus), then it will not be skipped, and will be put on device
    _no_placement_params = ["ple.ple_embedding.ngram_embedding.weight"]

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, Qwen4ExpTextGatedDeltaNet):
            init.ones_(module.dt_bias)
            # Lower bound kept away from 0 so log(A) never becomes -inf
            # Modification: empty_like keeps DTensor attributes so copy_ works under FSDP2 sharding
            init.copy_(module.A_log, torch.empty_like(module.A_log).uniform_(0.01, 16).log_())
        # We initialize with 0s to be 1 centered as the RMSNorm here does (1 + weight)
        elif isinstance(module, Qwen4ExpTextRMSNorm):
            init.zeros_(module.weight)
        elif isinstance(module, Qwen4ExpTextExperts):
            init.normal_(module.gate_up_proj, mean=0.0, std=self.config.initializer_range)
            init.normal_(module.down_proj, mean=0.0, std=self.config.initializer_range)
        elif isinstance(module, Qwen4ExpTextSparseMoeBlock):
            init.normal_(module.gate.weight, mean=0.0, std=self.config.initializer_range)
        if isinstance(module, Qwen4ExpTextNGramEmbedding):
            init.copy_(
                module.layer_multipliers,
                _build_layer_multipliers(
                    module.unigram_vocab_size, module.ngram_size, module.ple_layer_index, module.seed
                ),
            )
            init.copy_(module.ngram_heads_vocab_sizes, torch.tensor(module.head_vocab_sizes, dtype=torch.long))
            init.copy_(module.ngram_heads_offsets, torch.tensor(module.head_offsets, dtype=torch.long))
        elif isinstance(module, Qwen4ExpTextPLELayer):
            init.zeros_(module.conv1d.weight)


